<!DOCTYPE html>

<html lang="es"><head><meta charset="utf-8"/><meta content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover" name="viewport"/><meta content="mobile_blank" name="shell-type"/><link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;600;700&amp;display=swap" rel="stylesheet"/><link href="https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@24,400,0,0" rel="stylesheet"/>
<link href="https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:wght,FILL@100..700,0..1&amp;display=swap" rel="stylesheet"/><style>@layer base{html,body{width:100%;margin:0;padding:0;min-height:100%;}body{overscroll-behavior-y:none;}.pb-safe{padding-bottom:env(safe-area-inset-bottom,0px);}.pt-safe{padding-top:env(safe-area-inset-top,0px);}main>:first-child{margin-top:0!important;}main>:last-child{margin-bottom:0!important;}}::-webkit-scrollbar{display:none;}</style><script src="https://cdn.tailwindcss.com"></script><script id="tailwind-config">tailwind.config = { darkMode: "class", theme: { extend: { "colors": { "outline-variant": "#c0c9bb", "on-secondary-container": "#476d12", "error-container": "#ffdad6", "on-primary-fixed": "#002204", "on-primary-container": "#f7fff1", "tertiary-fixed-dim": "#ffb875", "background": "#eefeed", "on-tertiary": "#ffffff", "on-secondary": "#ffffff", "on-surface": "#121e14", "tertiary": "#894d00", "surface-tint": "#236c2b", "surface": "#eefeed", "on-primary-fixed-variant": "#005315", "surface-container-highest": "#d7e7d6", "primary-fixed-dim": "#8dd889", "surface-dim": "#cfdece", "on-tertiary-fixed": "#2d1600", "secondary-fixed-dim": "#a7d46f", "on-background": "#121e14", "secondary": "#43690d", "inverse-surface": "#263328", "on-error": "#ffffff", "on-primary": "#ffffff", "outline": "#707a6d", "on-secondary-fixed-variant": "#2f4f00", "on-tertiary-fixed-variant": "#6b3b00", "inverse-primary": "#8dd889", "tertiary-container": "#ab630a", "secondary-container": "#bfee85", "on-surface-variant": "#40493e", "primary-container": "#3b833f", "on-secondary-fixed": "#102000", "tertiary-fixed": "#ffdcc0", "primary": "#206928", "primary-fixed": "#a8f5a3", "surface-container-high": "#ddecdc", "inverse-on-surface": "#e5f5e4", "error": "#ba1a1a", "surface-container-lowest": "#ffffff", "surface-variant": "#d7e7d6", "surface-container": "#e3f2e1", "secondary-fixed": "#c2f188", "surface-container-low": "#e8f8e7", "on-tertiary-container": "#fffbff", "on-error-container": "#93000a", "surface-bright": "#eefeed" }, "borderRadius": { "DEFAULT": "0.25rem", "lg": "0.5rem", "xl": "0.75rem", "full": "9999px" }, "spacing": { "space-lg": "1.5rem", "space-sm": "0.5rem", "space-xs": "0.25rem", "space-xl": "2.25rem", "margin-tablet": "1.5rem", "gutter": "1.25rem", "margin": "1rem", "gutter-desktop": "1.5rem", "margin-desktop": "2.5rem", "space-md": "1rem" }, "fontFamily": { "headline-lg-mobile": ["Plus Jakarta Sans"], "label-md": ["Plus Jakarta Sans"], "headline-lg": ["Plus Jakarta Sans"], "body-lg": ["Plus Jakarta Sans"], "headline-md": ["Plus Jakarta Sans"], "body-md": ["Plus Jakarta Sans"], "body-sm": ["Plus Jakarta Sans"], "label-sm": ["Plus Jakarta Sans"], "label-lg": ["Plus Jakarta Sans"], "headline-sm": ["Plus Jakarta Sans"], "display-lg-mobile": ["Plus Jakarta Sans"], "display-lg": ["Plus Jakarta Sans"] }, "fontSize": { "headline-lg-mobile": ["1.5rem", { "lineHeight": "2rem", "fontWeight": "600" }], "label-md": ["0.75rem", { "lineHeight": "1rem", "letterSpacing": "0.02em", "fontWeight": "600" }], "headline-lg": ["2rem", { "lineHeight": "2.5rem", "letterSpacing": "-0.015em", "fontWeight": "600" }], "body-lg": ["1.0625rem", { "lineHeight": "1.625rem", "fontWeight": "400" }], "headline-md": ["1.375rem", { "lineHeight": "1.875rem", "fontWeight": "600" }], "body-md": ["0.9375rem", { "lineHeight": "1.5rem", "fontWeight": "400" }], "body-sm": ["0.8125rem", { "lineHeight": "1.25rem", "fontWeight": "400" }], "label-sm": ["0.6875rem", { "lineHeight": "0.875rem", "letterSpacing": "0.03em", "fontWeight": "600" }], "label-lg": ["0.875rem", { "lineHeight": "1.25rem", "letterSpacing": "0.01em", "fontWeight": "600" }], "headline-sm": ["1.125rem", { "lineHeight": "1.625rem", "fontWeight": "600" }], "display-lg-mobile": ["2rem", { "lineHeight": "2.5rem", "letterSpacing": "-0.01em", "fontWeight": "700" }], "display-lg": ["3rem", { "lineHeight": "3.5rem", "letterSpacing": "-0.02em", "fontWeight": "700" }] } } } };</script></head><body class="bg-surface font-body-md text-body-md text-on-surface min-h-screen flex flex-col antialiased selection:bg-secondary-container selection:text-on-secondary-container"><main class="flex-1 flex flex-col relative w-full bg-surface pt-safe pb-safe px-margin"><div class="flex flex-col w-full pb-space-lg">
<!-- Brand & Mascot Intro Card -->
<header class="flex flex-col items-center text-center pt-space-md pb-space-sm px-space-xs">
<!-- Emblem Container -->
<div class="relative flex items-center justify-center w-20 h-20 rounded-full bg-surface-container shadow-sm mb-space-sm">
<div class="absolute inset-0 rounded-full bg-secondary-container/20"></div>
<img alt="Isotipo oficial VetZen" class="w-16 h-16 object-contain relative z-10 drop-shadow-sm" src="https://lh3.googleusercontent.com/aida-public/AB6AXuA5LlwzhQcQssRXwEySFmOEV-OZKcT6lotg2sjVWl7FTksBU-qYQBmCLJDoUrvYc-j8qCIMON1xx4aJBwe_elcPub7jmk1KzgCTHELxD76LM0iFm8u5dyG3XGCOiyQxcscvy85WumwbFBm4SIRctzurBhMi732ltrh5ZYg6AZKEoF8x7XTPSbl_LZR0Ng5-LEzvF2iSg2TWXTpqH3bfmTV4A3PiB7m3Ca8UWoZl09qzVVZEFwmMLQFVzA"/>
</div>
<!-- Brand Typography -->
<h2 class="font-headline-lg-mobile text-headline-lg-mobile text-on-surface tracking-tight">VetZen</h2>
<p class="font-label-md text-label-md text-secondary mt-0.5 uppercase tracking-widest font-semibold">
      Gestión Veterinaria y Terapias
    </p>
<!-- Warm Welcome Copy -->
<div class="mt-space-md max-w-xs">
<h1 class="font-headline-md text-headline-md text-on-surface font-bold leading-tight">
        Bienvenido a VetZen
      </h1>
<p class="font-body-sm text-body-sm text-on-surface-variant mt-1.5 leading-relaxed">
        Gestioná tus pacientes, tratamientos y seguimiento desde un solo lugar.
      </p>
</div>
</header>
<!-- Login Form Box (Level 1 Elevation, Crisp Surface Layer) -->
<section class="w-full mt-space-sm">
<div class="bg-surface-container-lowest rounded-xl shadow-md p-space-md sm:p-space-lg flex flex-col gap-space-md">
<form class="flex flex-col gap-space-md" id="vetzen-login-form" onsubmit="event.preventDefault(); handleLogin();">
<!-- Email Field -->
<div class="flex flex-col gap-1.5">
<label class="font-label-lg text-label-lg text-on-surface font-semibold flex items-center justify-between" for="email-input">
<span>Correo electrónico</span>
<span class="material-symbols-outlined text-[18px] text-outline">mail</span>
</label>
<div class="relative">
<input autocomplete="email" class="w-full h-12 px-space-md bg-surface-container-low rounded-lg font-body-md text-body-md text-on-surface placeholder:text-outline outline-none transition-colors duration-150 focus:bg-surface-container-lowest focus:ring-2 focus:ring-primary/40 focus:ring-offset-1 text-base" id="email-input" placeholder="ejemplo@vetzen.com" required="" type="email"/>
</div>
</div>
<!-- Password Field -->
<div class="flex flex-col gap-1.5">
<label class="font-label-lg text-label-lg text-on-surface font-semibold flex items-center justify-between" for="password-input">
<span>Contraseña</span>
<span class="material-symbols-outlined text-[18px] text-outline">lock</span>
</label>
<div class="relative flex items-center">
<input autocomplete="current-password" class="w-full h-12 pl-space-md pr-12 bg-surface-container-low rounded-lg font-body-md text-body-md text-on-surface placeholder:text-outline outline-none transition-colors duration-150 focus:bg-surface-container-lowest focus:ring-2 focus:ring-primary/40 focus:ring-offset-1 text-base" id="password-input" placeholder="Ingresá tu contraseña" required="" type="password"/>
<button aria-label="Mostrar u ocultar contraseña" class="absolute right-2.5 p-2 rounded-lg text-outline-variant hover:text-on-surface transition-colors focus:outline-none" id="toggle-password" type="button">
<span class="material-symbols-outlined text-[20px] align-middle" id="password-visibility-icon">visibility</span>
</button>
</div>
</div>
<!-- Options: Remember & Recovery -->
<div class="flex items-center justify-between pt-1 pb-1">
<label class="flex items-center gap-2.5 cursor-pointer select-none py-1">
<input class="w-4 h-4 rounded text-primary accent-primary bg-surface-container-low focus:ring-0 cursor-pointer" id="remember-me" type="checkbox"/>
<span class="font-body-sm text-body-sm text-on-surface-variant font-medium">Recordarme</span>
</label>
<a class="font-body-sm text-body-sm text-secondary hover:text-on-secondary-container font-semibold transition-colors py-1 underline-offset-2 hover:underline" href="#recuperar">
            ¿Olvidaste tu contraseña?
          </a>
</div>
<!-- Primary Submit Button -->
<button class="w-full h-[50px] bg-primary hover:bg-primary-container active:scale-[0.99] text-on-primary font-label-lg text-label-lg font-bold rounded-lg shadow-sm transition-all duration-150 flex items-center justify-center gap-2 cursor-pointer mt-1" id="submit-btn" type="submit">
<span>Ingresar</span>
<span class="material-symbols-outlined text-[20px]">login</span>
</button>
</form>
</div>
</section>
<!-- Reassuring Clinical Care Badge -->
<div class="mt-space-lg mx-auto flex items-center gap-2 px-space-md py-1.5 rounded-full bg-surface-container text-on-surface-variant">
<span class="material-symbols-outlined text-[16px] text-primary" style="font-variation-settings: 'FILL' 1;">pets</span>
<span class="font-label-sm text-label-sm font-semibold tracking-wide">Plataforma clínica de confianza</span>
</div>
<!-- Discreet Technical Footer -->
<footer class="mt-space-lg flex flex-col items-center text-center gap-1.5 text-on-surface-variant">
<div class="flex items-center gap-1.5 font-label-sm text-label-sm text-outline">
<span class="material-symbols-outlined text-[14px] text-secondary">verified_user</span>
<span>Acceso seguro VetZen · Versión 2.4</span>
</div>
<div class="flex items-center gap-2 font-label-sm text-label-sm text-outline mt-0.5">
<a class="hover:text-on-surface transition-colors underline-offset-2 hover:underline" href="#terminos">Términos de servicio</a>
<span>·</span>
<a class="hover:text-on-surface transition-colors underline-offset-2 hover:underline" href="#privacidad">Privacidad</a>
</div>
</footer>
</div>
<script>
  (function() {
    const toggleBtn = document.getElementById('toggle-password');
    const pwdInput = document.getElementById('password-input');
    const eyeIcon = document.getElementById('password-visibility-icon');

    if (toggleBtn && pwdInput && eyeIcon) {
      toggleBtn.addEventListener('click', function() {
        const isPassword = pwdInput.getAttribute('type') === 'password';
        pwdInput.setAttribute('type', isPassword ? 'text' : 'password');
        eyeIcon.textContent = isPassword ? 'visibility_off' : 'visibility';
      });
    }

    window.handleLogin = function() {
      const email = document.getElementById('email-input').value;
      const pwd = document.getElementById('password-input').value;
      const submitBtn = document.getElementById('submit-btn');

      if (!email || !pwd) return;

      submitBtn.disabled = true;
      submitBtn.classList.add('opacity-90');
      submitBtn.innerHTML = `
        <span class="inline-block animate-spin material-symbols-outlined text-[20px]">progress_activity</span>
        <span>Validando acceso...</span>
      `;

      setTimeout(() => {
        submitBtn.innerHTML = `
          <span class="material-symbols-outlined text-[20px]">check_circle</span>
          <span>¡Acceso concedido!</span>
        `;
        submitBtn.classList.remove('bg-primary');
        submitBtn.classList.add('bg-primary-container');
      }, 1000);
    };
  })();
</script></main></body></html>